mkdir -p /app/bin /app/out; cat > /app/bin/crosstabs.py <<'EOF'
import csv
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone


def load_json(path):
    with open(path, encoding="utf-8-sig") as f:
        return json.load(f)


def read_exports(d):
    rows = []
    ed = os.path.join(d, "exports")
    if not os.path.isdir(ed):
        return rows
    for name in sorted(os.listdir(ed)):
        p = os.path.join(ed, name)
        if not name.endswith(".csv") or not os.path.isfile(p):
            continue
        with open(p, "rb") as f:
            text = f.read().decode("utf-8")
        if text.startswith("﻿"):
            text = text[1:]
        first = text.split("\n", 1)[0]
        delim = ","
        for c in (",", ";", "\t"):
            if c in first:
                delim = c
                break
        reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for cells in reader:
            cells = [c.strip() for c in cells]
            if header is None:
                header = cells
                continue
            if not any(cells):
                continue
            row = {}
            for i, h in enumerate(header):
                v = cells[i] if i < len(cells) else ""
                row[h] = v if v != "" else None
            rows.append(row)
    return rows


def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return timedelta(minutes=sign * (int(h) * 60 + int(m)))


def parse_time(s, meta):
    if meta.get("submitted_format") == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        return dt - parse_offset(meta["utc_offset"])
    s = s.replace("Z", "+00:00") if s.endswith("Z") else s
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).replace(tzinfo=None)


def parse_duration(s, meta):
    if meta.get("duration_format") == "clock":
        secs = 0
        for part in s.split(":"):
            secs = secs * 60 + int(part)
        return secs
    return int(float(s))


def to_int(v):
    return int(float(v))


def median2(vals):
    """Twice the median."""
    v = sorted(vals)
    n = len(v)
    if n % 2:
        return 2 * v[n // 2]
    return v[n // 2 - 1] + v[n // 2]


def main(indir, outfile):
    cb = load_json(os.path.join(indir, "codebook.json"))
    wt = load_json(os.path.join(indir, "weighting.json"))
    plan = load_json(os.path.join(indir, "tables.json"))
    versions = cb["versions"]
    vkeys = list(versions.keys())
    questions = cb["questions"]
    qby = {q["id"]: q for q in questions}
    min_page = cb.get("partial_min_page", 0)

    # ---- rows
    rows = []
    for r in read_exports(indir):
        v = r.get("form_version")
        if v not in versions:
            continue
        meta = versions[v]["meta"]
        rid = r.get(meta["id"])
        complete = r.get(meta["status"]) == meta["complete"]
        sub = r.get(meta["submitted"])
        t = parse_time(sub, meta) if sub is not None else datetime.min
        lp = r.get(meta["last_page"])
        lp = to_int(lp) if lp is not None else 0
        dur = r.get(meta["duration"])
        dur = parse_duration(dur, meta) if dur is not None else None
        rows.append({"v": v, "id": rid, "complete": complete, "t": t, "lp": lp,
                     "dur": dur, "raw": r})

    stats = {k: {"rows": 0, "duplicates": 0, "short_partials": 0, "speeders": 0,
                 "complete": 0, "partial": 0} for k in vkeys}
    for r in rows:
        stats[r["v"]]["rows"] += 1

    # ---- duplicates
    best = {}
    for r in rows:
        k = r["id"]
        b = best.get(k)
        if b is None or (r["complete"], r["t"]) > (b["complete"], b["t"]):
            best[k] = r
    kept = []
    for r in rows:
        if best[r["id"]] is r:
            kept.append(r)
        else:
            stats[r["v"]]["duplicates"] += 1
    # short partials
    k2 = []
    for r in kept:
